import Foundation

/// Sensitive-content filtering for the clipboard history (ROADMAP v0.6 CLIP, spec 26 §1.3).
/// Pure, UI-free predicates so they can be unit-tested in DMSCoreTests.
public enum ClipboardFilter {

    /// Pasteboard types that mark content as concealed / auto-generated / transient.
    /// Password managers and system autofill set these on the pasteboard item itself.
    public static let blockedPasteboardTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "org.nspasteboard.TransientType"
    ]

    /// Bundle identifiers of known password managers whose copies must never be recorded.
    public static let passwordManagerBundleIDs: Set<String> = [
        "com.1password.1password",
        "com.bitwarden.desktop",
        "org.keepassxc.keepassxc"
    ]

    /// Name fragments matched case-insensitively against bundle ID and localized app name.
    public static let passwordManagerNameFragments: [String] = [
        "1password",
        "bitwarden",
        "keepassxc"
    ]

    /// Returns true when the given bundle ID or app name belongs to a known password manager.
    public static func isPasswordManager(bundleID: String?, appName: String?) -> Bool {
        if let bundleID {
            let b = bundleID.lowercased()
            if passwordManagerBundleIDs.contains(b) { return true }
            if passwordManagerNameFragments.contains(where: { b.contains($0) }) { return true }
        }
        if let appName {
            let n = appName.lowercased()
            if passwordManagerNameFragments.contains(where: { n.contains($0) }) { return true }
        }
        return false
    }

    /// Decides whether a pasteboard change should be recorded in history.
    /// - Parameters:
    ///   - pasteboardTypes: union of the types of **all** pasteboard items in the change.
    ///     If any item carries a blocked (concealed/transient/auto-generated) type, the whole
    ///     change is rejected — multi-representation items must not leak a plain string copy.
    ///   - sourceBundleID / sourceAppName: frontmost application at capture time (the only
    ///     public source signal macOS offers). Password-manager origins are rejected.
    ///   - filterEnabled: the `clipboardFilterSensitive` kill switch.
    public static func shouldRecord(
        pasteboardTypes: [String],
        sourceBundleID: String?,
        sourceAppName: String?,
        filterEnabled: Bool
    ) -> Bool {
        guard filterEnabled else { return true }
        if pasteboardTypes.contains(where: { blockedPasteboardTypes.contains($0) }) {
            return false
        }
        if isPasswordManager(bundleID: sourceBundleID, appName: sourceAppName) {
            return false
        }
        return true
    }
}
